// Story and quest flags in a save slot: each is one bit of the byte at slot offset `offset`.
// The slot keeps the game's flag bank $7F0000-$7F01FF at slot offset 0x228, so $7F00NN is at 0x228 + 0xNN.
// Every entry is set by the DS game's own event scripts in the rooms listed in setBy (location ids).
// verified: checked by hand in those scripts and against real saves. The other labels come from outside
// research on the SNES game, matched to the DS rooms that set them; treat them as close, not exact.
// group is the game's own name for the area of the first room in setBy (English and French; no Japanese).

export interface SaveFlag {
  group: { en: string; fr: string }
  label: string
  offset: number
  bit: number
  setBy: readonly number[]
  verified: boolean
}

